import { chapters } from './chapters.js';
import { renderVisual, bindVisual } from './visuals.js';
import { resources, glossary, lessonTemplate } from './resources.js';
import { sourceMap, labResults, labRegistry } from './generated-data.js';
import { zeroSteps } from './zero.js';
import { bindLessonDemos, lessonDemos } from './lesson-demo.js';
import { sourceLessons } from './source-lessons.js';
import { renderZeroPage, renderSourcePage, renderChapterBridge, plainFlow } from './beginner-ui.js';
import { officialPages, renderOfficialPage } from './official-docs.js';
import { t, locale, isEnglish, switchLanguage } from './i18n.js';

const $=s=>document.querySelector(s), app=$('#app');
const ui=(zh,en)=>t(zh,en);
const stageNames={基础:ui('01 / 建立基础','01 / Foundations'),机制:ui('02 / 理解机制','02 / Mechanics'),源码:ui('03 / 阅读实现','03 / Implementation'),二开:ui('04 / 开始二开','04 / Extension')};
const stageDisplay=stage=>ui(stage,({基础:'Foundations',机制:'Mechanics',源码:'Implementation',二开:'Extension'})[stage]||stage);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const inline=s=>escape(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
const chapterLink=id=>`#/learn/${id}`;
const storageKey='loongsuite-field-guide-v1';
let state={checks:{},answers:{},done:[],notes:{},last:'orientation'};
try{const old=JSON.parse(localStorage.getItem(storageKey)||'null');if(old&&typeof old==='object')state={...state,...old};}catch{}
let currentRoute='',toastTimer;
let disposeLessonDemos=()=>{};
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast(ui('浏览器未允许保存；可导出笔记。','Your browser did not allow saving; you can export your notes.'));}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2400);}
const displaySymbol = value => isEnglish ? ({'CallContextImpl（测试用）':'CallContextImpl (test helper)','CallContextImpl 模板':'CallContextImpl template'}[value] || value) : value;
const number=id=>String(chapters.findIndex(c=>c.id===id)+1).padStart(2,'0');
const codeBlock=(code,lang='text',numbered=true)=>`<div class="code-frame"><div class="code-bar"><span>${escape(lang.toUpperCase())}</span><button class="copy-btn" data-copy>${ui('复制代码','Copy code')}</button></div><pre><code>${escape(code).split('\n').map((s,i)=>`${numbered?`<span class="line-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>`:''}${s}`).join('\n')}</code></pre><span hidden data-raw>${escape(code)}</span></div>`;
function footer(){return `<aside class="community-scope">${ui('本指南由社区独立维护，是可选的学习补充；当前版本要求以官方文档为准。代码摘录和实验输出保留原文。','An independent, community-maintained learning supplement. Use the official docs for current version requirements. Code excerpts and captured output retain their original text.')} <a href="${isEnglish?'https://alibaba.github.io/loongsuite-go/':'https://alibaba.github.io/loongsuite-go/zh/'}">${ui('阅读官方文档','Read the official docs')}</a></aside><footer class="footer"><span>LoongSuite Go Field Guide · ${ui('中文学习手册','Bilingual field guide')}</span><span>${ui('固定教学快照','Pinned teaching snapshot')} v1.15.0 / cac4009 · ${ui('2026-10-29 实例动画更新','Example animations updated 2026-10-29')}</span></footer>`;}
function languageButtons(){return `<div class="language-switch" role="group" aria-label="${ui('语言','Language')}"><button class="icon-btn" data-language="zh" aria-label="简体中文" aria-pressed="${!isEnglish}">中</button><button class="icon-btn" data-language="en" aria-label="English" aria-pressed="${isEnglish}">EN</button></div>`;}
function sidebar(route){return `<aside class="sidebar" id="sidebar" aria-label="${ui('课程导航','Course navigation')}"><a class="brand" href="#/"><span class="brand-mark" aria-hidden="true">L</span><span>LoongSuite Go<small>THE ENGINEERING FIELD GUIDE</small></span></a><button class="search-launch" data-search><span>⌕　${ui('搜索手册','Search guide')}</span><span class="key">⌘ K</span></button><nav class="utility-nav" aria-label="${ui('手册工具','Guide tools')}">${[['/','◈',ui('学习路线','Learning path')],['/start','01',ui('从零开始 · 七小步','Start here · 7 steps')],['/official',ui('官','↗'),ui('对照官方文档','Official docs')],['/source','⌘',ui('源码地图','Source map')],['/labs','⌁',ui('动手实验','Hands-on labs')],['/glossary','Aa',ui('术语速查','Glossary')],['/resources','↗',ui('编写方法与资源','Writing & resources')]].map(([path,icon,label])=>`<a href="#${path}" class="${(route===path||path!=='/'&&route.startsWith(path+'/'))?'active':''}" ${(route===path||path!=='/'&&route.startsWith(path+'/'))?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><nav class="chapter-nav" aria-label="${ui('分阶课程','Course stages')}">${['基础','机制','源码','二开'].map(stage=>`<div class="nav-label">${stageNames[stage]}</div>${chapters.filter(c=>c.stage===stage).map(c=>`<a href="${chapterLink(c.id)}" class="${route===`/learn/${c.id}`?'active':''}" ${route===`/learn/${c.id}`?'aria-current="page"':''}><span class="chapter-number ${state.done.includes(c.id)?'done':''}">${state.done.includes(c.id)?'✓':number(c.id)}</span><span>${escape(c.title.split('：')[0])}</span></a>`).join('')}`).join('')}</nav><div class="sidebar-footer"><div>${ui('你的学习进度','Your progress')} <b data-progress-label>${state.done.length} / ${chapters.length}</b></div><div class="progress-track" role="progressbar" aria-label="${ui('已完成章节','Completed chapters')}" aria-valuemin="0" aria-valuemax="${chapters.length}" aria-valuenow="${state.done.length}"><span style="width:${state.done.length/chapters.length*100}%"></span></div><span>${ui('进度与笔记保存在当前浏览器','Progress and notes are saved in this browser')}</span></div></aside><div class="mobile-scrim" data-close-menu></div>`;}
function shell(route,content,breadcrumb){return `${sidebar(route)}<div class="shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-menu aria-controls="sidebar" aria-expanded="false" aria-label="${ui('打开课程导航','Open course navigation')}">☰</button><span>FIELD NOTES</span><b>${escape(breadcrumb)}</b></div><div class="top-actions">${languageButtons()}<span class="version">v1.15.0 · ${ui('固定教学快照','Pinned teaching snapshot')}</span><button class="icon-btn print-btn" data-print>${ui('打印 / PDF','Print / PDF')}</button><button class="icon-btn" data-export title="${ui('导出学习笔记','Export study notes')}">${ui('导出笔记 ↓','Export notes ↓')}</button></div></header><main id="main" class="page" tabindex="-1">${content}${footer()}</main></div>`;}
function overview(){const stages=[['基础',ui('先把 Go 与遥测说清楚','Make Go and telemetry clear'),ui('知道每个对象是谁、每个 ID 从哪来。','Know what each object is and where every ID comes from.')],['机制',ui('跟随一次构建','Follow one build'),ui('从编译输入，走到能运行的探针。','Trace compiler input to a running probe.')],['源码',ui('把图映射到函数','Map the diagram to functions'),ui('进入规则、跳板与运行时桥接。','Enter the rules, trampolines, and runtime bridge.')],['二开',ui('做一个能证明的改动','Make a change you can prove'),ui('写规则、保语义、测兼容与回滚。','Write rules, preserve semantics, and test compatibility and rollback.')]];return `<section class="hero"><div><div class="eyebrow">A GUIDED JOURNEY · ${ui('从 0 到能二开','from zero to extending it')}</div><h1>${ui('读懂插桩，','Understand instrumentation,')}<br>${ui('再亲手','then')}<em>${ui('改写。','rewrite it.')}</em></h1><p>${ui('先从一个查房间的函数开始，弄清包、模块和构建。理解为什么需要观察代码，再一步步走到 LoongSuite 的真实实现。','Start with a function that checks a room. Learn packages, modules, and builds; understand why observation matters; then follow the path into LoongSuite’s real implementation.')}</p><div class="hero-footer"><a class="btn" href="${state.done.length?chapterLink(state.last):'#/start/1'}">${state.done.length?ui('继续学习','Continue learning'):ui('从零开始 · 第一步','Start here · step one')} <span>→</span></a><a class="btn light" href="#/official">${ui('跟着官方文档读 ↗','Read with the official docs ↗')}</a><a class="btn light" href="#/source/deps">${ui('为什么要补依赖？ ↗','Why add dependencies? ↗')}</a><a class="btn light" href="#/source/preprocess">${ui('看三轮准备的实例动画 ↗','See the three-pass example ↗')}</a></div></div><figure class="hero-figure"><div class="figure-label">${ui('先看两段时间，暂时不用背名词','See two timelines before memorizing terms')}</div>${plainFlow([[ui('源码','Source'),ui('你编写的 .go 文件','The .go files you write')],[ui('构建','Build'),ui('工具准备依赖并加工代码','The tool prepares dependencies and transforms code')],[ui('运行','Run'),ui('启动生成的程序，处理请求','The generated program starts and handles requests')]],escape)}<figcaption class="figure-caption">${ui('LoongSuite 参与“构建”，把观察动作接入程序。','LoongSuite participates in the “build” phase and connects observation into the program.')}<br>${ui('程序“运行”时，这些动作才真正记录请求。','Only when the program “runs” do these actions record requests.')}</figcaption></figure></section><div class="learning-meta"><span><b>7</b>${ui('入门小步','starter steps')}</span><span><b>${chapters.length}</b>${ui('递进章节','progressive chapters')}</span><span><b>${sourceMap.length}</b>${ui('源码入口','source entry points')}</span><span><b>${labRegistry.length}</b>${ui('本地实验','local labs')}</span><span>${ui('阅读 + 实践约','Reading + practice: about')} ${Math.round(chapters.reduce((n,c)=>n+c.minutes,0)/60)} ${ui('小时，按自己的节奏推进','hours, at your pace')}</span></div><section><div class="section-head"><h2>${ui('从基础，到可验证的二开','From foundations to verifiable extensions')}</h2><p>${ui('建议顺序阅读；已有基础可以直接进入对应章节。','The suggested order is sequential; jump to a chapter if you already have the foundations.')}</p></div><div class="roadmap">${stages.map(([name,title,desc],i)=>`<section class="stage"><div class="stage-index">STAGE ${String(i+1).padStart(2,'0')}</div><h3>${title}</h3><p>${desc}</p><ul>${chapters.filter(c=>c.stage===name).map(c=>`<li><a href="${chapterLink(c.id)}"><span>${number(c.id)}</span>${escape(c.title.split('：')[0])} ${state.done.includes(c.id)?'✓':'↗'}</a></li>`).join('')}</ul></section>`).join('')}</div></section><aside class="practice-banner"><div><div class="eyebrow" style="color:var(--lime);margin-bottom:10px">LEARN BY CHANGING ONE THING</div><h2>${ui('从“我看懂了”，走到“我能证明”。','Move from “I understand it” to “I can prove it.”')}</h2><p>${ui('改一次 context、一个版本区间、一段 hook。比较输入、输出与父子关系，再回到源码解释原因。','Change one context, one version range, or one hook. Compare inputs, outputs, and parent-child relationships, then return to the source to explain why.')}</p></div><a href="#/labs" class="btn lime">${ui('打开实验台 →','Open the workbench →')}</a></aside><div class="promise-grid"><section><h2>${ui('你最终要交付什么？','What will you deliver?')}</h2><p>${ui('一个自己的自定义规则、匹配的 hook、原版与插桩的对照输出、一份兼容矩阵。毕业课会把这些组装成一次完整、可回滚的二开。','A custom rule, a matching hook, before-and-after output, and a compatibility matrix. The capstone assembles them into a complete, reversible extension.')}</p><a href="${chapterLink('capstone')}">${ui('查看毕业项目与验收条件 →','View the capstone and acceptance criteria →')}</a></section><section><h2>${ui('这份手册如何建立信任？','How does this guide earn trust?')}</h2><p>${ui('源码链接固定到提交；页面交互标明是教学模型；实验独立记录真实执行状态。上游能力、已有 OTel 服务的兼容设计、未验证边界分别说明。','Source links are pinned to a revision; interactions are marked as teaching models; labs record real execution status independently. Upstream capabilities, compatibility with existing OTel services, and unverified boundaries are stated separately.')}</p><a href="#/resources">${ui('查看参考方法与来源 →','View methods and sources →')}</a></section></div><div class="callout"><b>${ui('学习约定','Learning agreement')}</b>　${ui('会写基本 Go 函数即可开始。不要先把所有规则读一遍：先跑通一个小实验，再追踪它对应的编译路径。网站不执行 Go；实验包在你的本地终端运行。','Basic Go functions are enough to begin. Do not read every rule first: run a small lab, then trace its compilation path. This site does not execute Go; run the lab package in your local terminal.')}</div><div class="toolbar"><a class="btn light" href="./assets/labs.zip" download>${ui('下载本地实验包 ↓','Download local labs ↓')}</a><a class="btn light" href="./offline.html" download>${ui('下载离线单文件手册 ↓','Download offline guide ↓')}</a><a class="btn light" href="./guide.md" download>${ui('下载 Markdown 正文 ↓','Download Markdown source ↓')}</a></div>`;}
function renderSection(s,i){return `<section class="article-section" id="section-${i}"><h2>${escape(s.title)}</h2>${(s.paragraphs||[]).map(p=>`<p>${inline(p)}</p>`).join('')}${s.code?codeBlock(s.code,s.language):''}${s.note?`<aside class="callout">${inline(s.note)}</aside>`:''}</section>`;}
function chapterPage(c,print=false){const idx=chapters.indexOf(c),checks=state.checks[c.id]||[],answers=state.answers[c.id]||{};const verdict=ok=>ok?ui('✓ 回答正确。','✓ Correct.'):ui('再想一想。','Try again.');const body=`<article class="article"><header class="chapter-header"><div class="eyebrow">LESSON ${number(c.id)} / ${stageDisplay(c.stage)}</div><h1>${escape(c.title)}</h1><p class="subtitle">${escape(c.subtitle)}</p><div class="chapter-info"><span>${ui('建议','Suggested')} ${c.minutes} ${ui('分钟 · 含实践','min · includes practice')}</span><span>${ui('前置：','Prerequisites:')}${c.prerequisites.map(p=>chapters.find(x=>x.id===p)?.title.split('：')[0]||p).map(escape).join(' / ')}</span></div></header>${renderChapterBridge(c,{inline,escape})}<section class="outcomes"><h2>${ui('完成本章，你能做到','By the end of this chapter, you can')}</h2><ul>${c.outcomes.map(x=>`<li>${inline(x)}</li>`).join('')}</ul></section>${print?'':c.stage==='基础'?plainFlow([[ui('普通函数','Ordinary function'),ui('先理解原来的动作','Understand the original action')],[ui('观察代码','Instrumented code'),ui('解释为何需要增加记录','Explain why recording is added')],[ui('自动接入','Automatic integration'),ui('再到源码核实怎样做到','Verify how it works in source')]],escape):c.visual==='pipeline'?'':renderVisual(c.visual||'pipeline')}${c.sections.map(renderSection).join('')}<section class="article-section" id="source-reading"><h2>${ui('回到源码，带着问题读','Return to the source with questions')}</h2><ol class="source-walk">${c.walkthrough.map(w=>`<li><div><a href="${escape(w.url)}" target="_blank" rel="noopener noreferrer">${escape(w.file)} ↗</a><p><strong>${escape(displaySymbol(w.symbol))}</strong> · ${inline(w.task)}</p></div></li>`).join('')}</ol><a href="#/source">${ui('在源码地图中按调用路径定位 →','Locate it by call path in the source map →')}</a></section><section class="article-section" id="lab"><div class="lab-box"><div class="eyebrow">TRY IT YOURSELF</div><h2>${escape(c.lab.title)}</h2><ol>${c.lab.steps.map(x=>`<li>${inline(x)}</li>`).join('')}</ol>${codeBlock(c.lab.command,'sh')}<div class="expected"><b>${ui('观察与验收：','Observe and verify:')}</b>${inline(c.lab.expected)}</div><p style="margin-top:16px;margin-bottom:0"><b>${ui('再改一步：','Change one more thing:')}</b>${inline(c.lab.challenge)}</p></div><div class="callout">${ui('可运行实验与真实验证状态见','See runnable labs and real verification status on the')} <a href="#/labs">${ui('动手实验页','labs page')}</a>。${ui('正文内的概念代码若没有完整模块、import 和测试，是阅读示意，不是可直接运行的完整程序。','Conceptual code without a complete module, imports, and tests is illustrative, not a complete runnable program.')}</div></section><section class="article-section" id="quiz"><h2>${ui('先回答，再继续','Answer before continuing')}</h2>${c.quiz.map((q,i)=>`<fieldset class="quiz" data-quiz="${i}"><legend>${i+1}. ${escape(q.q)}</legend>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="quiz-${c.id}-${i}" value="${j}" ${answers[i]===j?'checked':''}><span>${inline(o)}</span></label>`).join('')}<div class="feedback ${answers[i]===q.answer?'':'incorrect'}" ${answers[i]===undefined?'hidden':''}>${verdict(answers[i]===q.answer)} ${inline(q.explanation)}</div></fieldset>`).join('')}</section><section class="article-section" id="checkpoint"><h2>${ui('本章能力检查','Chapter capability check')}</h2><p>${ui('测验正确后，再确认你能独立完成以下动作。自评用于帮助学习，不代替实验执行记录。','After the quiz, confirm that you can complete these actions independently. Self-assessment supports learning; it does not replace execution records.')}</p><div class="checkpoint">${c.checkpoint.map((x,i)=>`<label><input type="checkbox" data-check="${i}" ${checks.includes(i)?'checked':''}><span>${inline(x)}</span></label>`).join('')}<div class="completion-row"><button class="btn" data-complete>${state.done.includes(c.id)?`✓ ${ui('已完成本章','Chapter complete')}`:ui('标记本章完成','Mark chapter complete')}</button><small data-completion-help></small></div></div></section><section class="article-section" id="notes"><h2>${ui('写下你自己的解释','Write your own explanation')}</h2><label class="notes-label" for="chapter-notes"><span>${ui('用三句话说明：它解决什么、在哪里实现、怎样验证。','In three sentences: what it solves, where it is implemented, and how to verify it.')}</span><span data-note-status>${ui('自动保存到浏览器','Saved automatically in this browser')}</span></label><textarea id="chapter-notes" class="notes" placeholder="${ui('我原先以为…\n通过实验发现…\n接下来我要在源码中确认…','I originally thought…\nThe experiment showed…\nNext I will confirm in the source…')}">${escape(state.notes[c.id]||'')}</textarea></section><section class="article-section" id="references"><h2>${ui('本章来源','Chapter sources')}</h2><ul>${c.sources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a></li>`).join('')}</ul></section>${print?'':`<nav class="prev-next" aria-label="${ui('相邻章节','Adjacent chapters')}">${idx>0?`<a href="${chapterLink(chapters[idx-1].id)}"><small>← ${ui('上一章','Previous')}</small>${escape(chapters[idx-1].title)}</a>`:`<a href="#/"><small>← ${ui('回到路线','Back to path')}</small>${ui('查看学习全景','View learning overview')}</a>`}${idx<chapters.length-1?`<a href="${chapterLink(chapters[idx+1].id)}"><small>${ui('下一章','Next')} →</small>${escape(chapters[idx+1].title)}</a>`:`<a href="#/labs"><small>${ui('继续实践','Keep practicing')} →</small>${ui('打开实验与二开任务','Open labs and extension tasks')}</a>`}</nav>`}</article>`;return print?body:`<div class="chapter-layout">${body}<aside class="toc" aria-label="${ui('本章目录','Chapter contents')}"><h2>${ui('本章阅读路径','Chapter path')}</h2><a href="#chapter-bridge" data-scroll="chapter-bridge">${ui('先解释为什么与新名词','Explain why and new terms')}</a>${c.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${escape(s.title)}</a>`).join('')}${[['source-reading',ui('源码阅读','Read the source')],['lab',ui('动手练习','Hands-on practice')],['quiz',ui('检查理解','Check understanding')],['checkpoint',ui('能力检查','Capability check')],['notes',ui('我的笔记','My notes')]].map(([id,label])=>`<a href="#${id}" data-scroll="${id}">${label}</a>`).join('')}<div class="toc-tools"><a href="./assets/labs.zip" download>${ui('下载实验包 ↓','Download labs ↓')}</a><a href="./offline.html" download>${ui('离线手册','Offline guide')}</a></div></aside></div>`;}
function sourcePage(selected=sourceMap[0]?.id){const s=sourceMap.find(x=>x.id===selected)||sourceMap[0];return renderSourcePage(s,sourceLessons[s.id],sourceMap,{inline,escape,codeBlock});}
function labsPage(){return `<div class="eyebrow">THE WORKBENCH / ${ui('运行以后再下结论','Conclude only after running')}</div><h1>${ui('一次只改变一个变量。','Change one variable at a time.')}</h1><p>${ui('实验在本地 Go 环境运行，页面不会调用业务接口，也不冒充在线 Go IDE。下载后先读 README，再按实验顺序进行。','Labs run in a local Go environment. This page does not call business APIs or pretend to be an online Go IDE. Read the README after downloading, then follow the lab order.')}</p><div class="toolbar"><a class="btn" href="./assets/labs.zip" download>${ui('下载实验源码 ↓','Download lab source ↓')}</a><a class="btn light" href="./lab-results.json" download>${ui('下载执行记录 ↓','Download execution record ↓')}</a></div><div class="callout"><b>${ui('验证口径：','Verification scope:')}</b>${ui('标准库机制实验、自定义 hook 编译实验、OTel SDK 实验分别标记。某个实验通过，不代表真实业务环境所有路径已验收。工具与依赖需要网络时，下载发生在你的终端。','Standard-library, custom-hook compilation, and OTel SDK labs are marked separately. Passing one lab does not validate every path in a real service. If tools or dependencies need the network, download them from your terminal.')}</div><div class="callout"><b>${ui('第一次学习，从 00 开始：','First time here? Start at 00:')}</b>${ui('先运行普通 Go 函数，再逐个进入后面的机制实验。','Run the ordinary Go function first, then work through the mechanism labs.')} <code>run-all.sh</code> ${ui('是完整检查脚本，适合完成学习后使用。','is the full check script for after you finish.')}</div>${codeBlock('unzip labs.zip\ncd labs/00-start\ngo run .','sh')}${labRegistry.map((l,i)=>`<section class="lab-entry" id="lab-${i+1}"><div class="eyebrow">LAB ${escape(l.id.split('-')[0])} <span class="lab-status">${escape(l.status)}</span></div><h2>${escape(l.title)}</h2><p>${inline(l.goal)}</p>${codeBlock(l.command,'sh')}<div class="two-columns"><section><h3>${ui('观察哪一个证据？','Which evidence should you observe?')}</h3><p>${inline(l.expected)}</p></section><section><h3>${ui('再做一个改动','Make one more change')}</h3><p>${inline(l.challenge)}</p></section></div><details><summary>${ui('展开参考解释与排查方向','Show reference explanation and troubleshooting')}</summary><p>${inline(l.answer)}</p>${l.output?codeBlock(l.output,'text'):''}</details></section>`).join('')}<section class="article-section"><h2>${ui('从实验走向自己的规则','From experiments to your own rule')}</h2><p>${ui('先让只读 hook 正常编译、执行并保留原返回值；再把 OTel Span 接进去。修改参数、返回值、runtime/GLS 都应建立独立回归，不能用一个成功截图替代。','First make a read-only hook compile, run, and preserve the original return value; then connect an OTel Span. Changes to parameters, return values, runtime, or GLS each need an independent regression; one successful screenshot is not enough.')}</p><a href="${chapterLink('capstone')}" class="btn">${ui('进入毕业项目 →','Open the capstone →')}</a></section>`;}
function legacyResourcesPage(){return ''}
function resourcesPage(){return `<div class="eyebrow">WRITING THE GUIDE / ${ui('编写方法与模板','Writing methods and templates')}</div><h1>${ui('好的指南，先设计学习。','A good guide designs the learning first.')}</h1><div class="toolbar"><a class="btn light" href="${isEnglish?'./guide-authoring-resources.en.md':'./guide-authoring-resources.md'}" download>${ui('下载资源对比 ↓','Download resource comparison ↓')}</a><a class="btn light" href="${isEnglish?'./chapter-template.en.md':'./chapter-template.md'}" download>${ui('下载章节模板 ↓','Download chapter template ↓')}</a></div><p>${ui('这些资源承担不同工作：skill 帮助组织与审稿，方法决定学习体验，文档框架负责呈现。下面是针对这份 Go 源码课程的选择依据，核对日期为 2026-10-27。','These resources serve different roles: skills organize and review, methods shape the learning experience, and documentation frameworks handle presentation. This is the rationale for this Go source course, checked 2026-10-27.')}</p><div class="callout"><b>${ui('本次选择：','This guide chooses:')}</b>teach + Diátaxis + Google’s reader and example methods + doc-coauthoring. ${ui('界面采用原生 HTML/CSS/JS，便于离线与自定义图解；没有为了套模板而引入 React/Vue。','The interface uses native HTML/CSS/JS for offline use and custom diagrams; React/Vue were not added just to fit a template.')}</div><div class="table-scroll"><table class="reference-table"><thead><tr><th>${ui('你需要什么','Need')}</th><th>${ui('优先考虑','Prefer')}</th><th>${ui('选择原因','Why')}</th></tr></thead><tbody>${[['从零学会一套技术','Learn a technology from zero','Diátaxis + 可验证实验','Diátaxis + verifiable labs','先设计读者动作和成功反馈，再补解释。','Design reader actions and feedback before adding explanation.'],['让 AI 协助写长文','Use AI to write long docs','doc-coauthoring','doc-coauthoring','先整理证据与读者目标，再做无上下文读者检查。','Organize evidence and reader goals before an out-of-context reader check.'],['长期维护内容型文档','Maintain content docs','Starlight','Starlight','现成文档导航、搜索与组件，维护成本相对集中。','Navigation, search, and components are ready-made.'],['在文中加入复杂互动','Add complex interaction','VitePress / Docusaurus','VitePress / Docusaurus','分别利用 Vue / React 组件；选择团队熟悉的生态。','Use Vue / React components; choose the ecosystem the team knows.'],['短篇但深入的互动手册','A short, deep interactive guide','原生网页 + 小组件','Native web + small widgets','可离线、无需构建依赖，交互围绕学习问题设计。','Offline, dependency-free, and centered on learning questions.']].map(([a,b,c,d,e,f])=>`<tr><td>${ui(a,b)}</td><td>${ui(c,d)}</td><td>${ui(e,f)}</td></tr>`).join('')}</tbody></table></div>${resources.map(r=>`<section class="resource-item"><div><span class="tag">${escape(r.kind)}</span><h2 style="font-size:20px;margin:12px 0 6px">${escape(r.name)}</h2><a href="${escape(r.url)}" target="_blank" rel="noopener noreferrer">${ui('官方 / GitHub ↗','Official / GitHub ↗')}</a></div><div><p><b>${ui('适合：','Good for:')}</b>${inline(r.fit)}</p><p><b>${ui('局限：','Limits:')}</b>${inline(r.limit)}</p><p><b>${ui('本指南的借鉴：','Used in this guide:')}</b>${inline(r.adopt)}</p><a href="${escape(r.docs)}" target="_blank" rel="noopener noreferrer">${ui('阅读原始说明 ↗','Read the original docs ↗')}</a>${r.install?codeBlock(r.install,'sh'):''}</div></section>`).join('')}<section class="article-section"><h2>${ui('一份可以复用的教学章节模板','A reusable teaching chapter template')}</h2><p>${ui('模板的关键是让每一步产出证据，而不是每章重复“概述、特点、总结”。复制后，用具体函数、版本和输出替换泛化内容。','The template makes each step produce evidence instead of repeating “overview, features, summary.” Replace generic content with concrete functions, versions, and output.')}</p>${codeBlock(lessonTemplate,'markdown')}</section><section class="article-section"><h2>${ui('本手册的质量门槛','Quality bar for this guide')}</h2><ol>${[ui('每个术语在第一次出现时解释，并能连回具体源码。','Explain each term at first use and connect it to source.'),ui('源码路径存在，链接固定到提交，阅读问题有明确目标。','Source paths exist, links are pinned, and reading questions have clear goals.'),ui('可运行代码必须有命令、前置、预期和真实状态；示意代码清楚标注。','Runnable code has commands, prerequisites, expected output, and real status; illustrative code is marked.'),ui('图解表达因果，不用装饰动画替代解释。','Diagrams express causality rather than replacing explanation with decoration.'),ui('完成不等于读过：你能复现实验、修改输入，再解释差异。','Completion means reproducing the lab, changing input, and explaining the difference.')].map(x=>`<li>${x}</li>`).join('')}</ol></section>`;}
function glossaryPage(){return `<div class="eyebrow">THE GLOSSARY / ${ui('快速找回概念','Find concepts quickly')}</div><h1>${ui('让每个名词都有落点。','Give every term an anchor.')}</h1><p>${ui('阅读源码时遇到陌生词，先确认它属于编译期、运行时，还是采集后端。不要把同一层的对象混作另一层的能力。','When a source term is unfamiliar, first identify whether it belongs to compile time, runtime, or the collection backend. Do not confuse objects from one layer with capabilities from another.')}</p><label class="sr-only" for="glossary-search">${ui('筛选术语','Filter terms')}</label><input class="filter-input" id="glossary-search" type="search" placeholder="${ui('搜索 AST、carrier、GLS…','Search AST, carrier, GLS…')}"><dl class="glossary">${glossary.map(([term,def])=>`<div data-term><dt>${escape(term)}</dt><dd>${inline(def)}</dd></div>`).join('')}</dl>`;}
function getRoute(){const raw=location.hash.slice(1)||'/';return raw.startsWith('/')?raw:'/';}
function render(){disposeLessonDemos();const route=getRoute(),[_,type,id]=route.split('/');currentRoute=route;let content,label;if(type==='learn'){const c=chapters.find(c=>c.id===id);if(!c){location.hash='/';return;}state.last=c.id;persist();content=chapterPage(c);label=`${number(c.id)} / ${c.title.split('：')[0]}`;}else if(type==='start'){content=renderZeroPage(id,{inline,escape,codeBlock});label=ui('从零开始 · 七小步','Start here · Seven steps');}else if(type==='official'){content=renderOfficialPage(id,{inline,escape})
label=ui('对照官方文档','Official docs companion')
}else if(type==='source'){content=sourcePage(id);label=ui('源码地图','Source map');}else if(type==='labs'){content=labsPage();label=ui('动手实验','Hands-on labs');}else if(type==='resources'){content=resourcesPage();label=ui('编写方法与资源','Writing methods and resources');}else if(type==='glossary'){content=glossaryPage();label=ui('术语速查','Glossary');}else{content=overview();label=ui('学习路线','Learning path');}
 if(type==='resources')content+=`<aside class="callout"><b>${ui('官方文档优先：','Official docs are authoritative:')}</b> ${ui('本页的社区资源是可选补充；遇到冲突时，以官方文档和固定源码为准。','Community resources here are optional supplements; when they conflict, follow the official docs and pinned source.')}</aside>`;content=content.replace('href="./guide.md"',`href="./${isEnglish?'guide.en.md':'guide.md'}"`);app.innerHTML=shell(route,content,label);document.documentElement.lang=isEnglish?'en':'zh-CN';document.title=`${label} · LoongSuite Go ${ui('学习手册','Field Guide')}`;document.querySelector('meta[name="description"]')?.setAttribute('content',ui('面向初学者的 LoongSuite Go 双语源码学习指南。','A bilingual source guide to LoongSuite Go for beginners.'));bindVisual(app);disposeLessonDemos=bindLessonDemos(app);bindGeneral();if(type==='learn')bindChapter(chapters.find(c=>c.id===id));if(type==='source')bindSource();if(type==='glossary')$('#glossary-search').addEventListener('input',e=>app.querySelectorAll('[data-term]').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(e.target.value.toLowerCase())));window.scrollTo(0,0);
}
function bindGeneral(){app.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>switchLanguage(b.dataset.language));app.querySelectorAll('[data-search]').forEach(b=>b.onclick=openSearch);app.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(b.closest('.code-frame').querySelector('[data-raw]').textContent));app.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});app.querySelectorAll('[data-export]').forEach(b=>b.onclick=exportNotes);app.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>window.print());app.querySelector('[data-menu]')?.addEventListener('click',()=>{const open=$('.sidebar').classList.toggle('open');$('.mobile-scrim').classList.toggle('open',open);$('[data-menu]').setAttribute('aria-expanded',String(open));});app.querySelector('[data-close-menu]')?.addEventListener('click',()=>{$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('open');$('[data-menu]').setAttribute('aria-expanded','false');});}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(ui('已复制','Copied'));}catch{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?ui('已复制','Copied'):ui('请选中代码后复制','Select the code and copy it'));}}
function eligible(c){return c.quiz.every((q,i)=>state.answers[c.id]?.[i]===q.answer)&&c.checkpoint.every((_,i)=>(state.checks[c.id]||[]).includes(i));}
function updateCompletion(c){const ok=eligible(c),done=state.done.includes(c.id);$('[data-complete]').disabled=!ok&&!done;$('[data-completion-help]').textContent=done?ui('完成记录已保存在当前浏览器。','Completion is saved in this browser.'):ok?ui('测验与能力检查已完成，可以进入下一章。','Quiz and capability checks are complete; you can continue.'):ui('答对本章测验，并确认全部能力检查后解锁。','Answer the quiz correctly and complete every capability check to unlock the next chapter.');}
function bindChapter(c){app.querySelectorAll('[data-quiz]').forEach(field=>field.addEventListener('change',e=>{const i=Number(field.dataset.quiz),j=Number(e.target.value);state.answers[c.id]||={};state.answers[c.id][i]=j;persist();const feedback=field.querySelector('.feedback');feedback.hidden=false;feedback.classList.toggle('incorrect',j!==c.quiz[i].answer);feedback.innerHTML=`${j===c.quiz[i].answer?ui('✓ 回答正确。','✓ Correct.'):ui('再想一想。','Try again.')} ${inline(c.quiz[i].explanation)}`;updateCompletion(c);}));app.querySelectorAll('[data-check]').forEach(input=>input.addEventListener('change',()=>{const i=Number(input.dataset.check),v=new Set(state.checks[c.id]||[]);input.checked?v.add(i):v.delete(i);state.checks[c.id]=[...v];persist();updateCompletion(c);}));$('[data-complete]').onclick=()=>{if(!eligible(c))return;if(!state.done.includes(c.id))state.done.push(c.id);persist();render();toast(ui('已完成本章，学习进度已保存。','Chapter complete; progress saved.'));};$('#chapter-notes').addEventListener('input',e=>{state.notes[c.id]=e.target.value;persist();$('[data-note-status]').textContent=ui('已保存','Saved');});updateCompletion(c);}
function bindSource(){app.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{location.hash=`/source/${b.dataset.source}`;});$('#source-filter')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();app.querySelectorAll('[data-source]').forEach(n=>{const s=sourceMap.find(s=>s.id===n.dataset.source);n.hidden=![s.title,s.path,s.symbol,s.role,sourceLessons[s.id]?.title,sourceLessons[s.id]?.plain].join(' ').toLowerCase().includes(q);});const empty=app.querySelector('.source-no-results');if(empty)empty.hidden=Array.from(app.querySelectorAll('[data-source]')).some(n=>!n.hidden);});}
const dialog=$('#search-dialog');function openSearch(){dialog.showModal();$('#global-search').value='';search('');$('#global-search').focus();}$('#close-search').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dialog.open?dialog.close():openSearch();}});$('#global-search').addEventListener('input',e=>search(e.target.value));
function demoSearchText(kind,id){const d=lessonDemos[kind]?.[id];return d?[d.title,d.scenario,...d.cases.flatMap(c=>c.frames.flatMap(f=>[f.title,f.explain,f.code.text]))].join(' '):'';}
function search(q){const word=q.toLowerCase().trim();const hits=[];
 for(const [i,s]of zeroSteps.entries()){const text=[s.title,s.question,...s.paragraphs,...s.terms.map(t=>t.term+' '+t.meaning),demoSearchText('zero',s.id)].join(' ');if(!word||text.toLowerCase().includes(word))hits.push({title:`${ui('从零','Step')} ${i+1} · ${s.title}`,url:`#/start/${i+1}`,detail:s.question});}
 for(const c of chapters){const text=[c.title,c.subtitle,...c.sections.flatMap(s=>[s.title,...s.paragraphs]),...c.bridge.terms.map(t=>t.term+' '+t.meaning),demoSearchText('chapter',c.id)].join(' ');if(!word||text.toLowerCase().includes(word)){const at=text.toLowerCase().indexOf(word);hits.push({title:`${number(c.id)} · ${c.title}`,url:chapterLink(c.id),detail:word?text.slice(Math.max(0,at-25),at+100):c.subtitle});}}
 for(const s of sourceMap){const lesson=sourceLessons[s.id];if(word&&[s.title,s.path,s.symbol,s.role,lesson.title,lesson.plain,...lesson.terms.map(t=>t.term+' '+t.meaning),demoSearchText('source',s.id)].join(' ').toLowerCase().includes(word))hits.push({title:lesson.title,url:`#/source/${s.id}`,detail:s.path});}
 for(const p of officialPages)if(word&&[p.title,p.group.title,p.says,p.gap,p.question].join(' ').toLowerCase().includes(word))hits.push({title:`${ui('官方文档对照','Official docs companion')} · ${p.group.title} · ${p.title}`,url:`#/official/${p.id}`,detail:p.path})
 $('#search-results').innerHTML=hits.length?hits.slice(0,30).map(x=>`<a href="${x.url}">${escape(x.title)}<small>${escape(x.detail)}</small></a>`).join(''):`<p class="empty">${ui('没有匹配结果。试试 module、依赖、context、采样或 hook。','No matches. Try module, dependency, context, sampling, or hook.')}</p>`;$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>dialog.close());}
function exportNotes(){let text=ui('# LoongSuite Go 学习记录\n\n源码版本：v1.15.0 / cac400935add57d8219122ba32857b8f55ac6eb1\n\n','# LoongSuite Go learning notes\n\nSource snapshot: v1.15.0 / cac400935add57d8219122ba32857b8f55ac6eb1\n\n');for(const c of chapters){text+=`## ${number(c.id)} ${c.title}\n\n${ui('状态：','Status: ')}${state.done.includes(c.id)?ui('已完成','Completed'):ui('学习中 / 未完成','In progress / not completed')}\n\n${state.notes[c.id]||ui('（暂无笔记）','(No notes yet)')}\n\n`;for(const [i,item]of c.checkpoint.entries())text+=`- [${(state.checks[c.id]||[]).includes(i)?'x':' '}] ${item}\n`;text+='\n';}const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='loongsuite-learning-notes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(ui('学习笔记已导出','Learning notes exported'));}
function initStaticUI(){document.documentElement.lang=isEnglish?'en':'zh-CN';document.title=ui('LoongSuite Go · 从原理到二开','LoongSuite Go · From principles to extensions');document.querySelector('meta[name="description"]')?.setAttribute('content',ui('从 Go 编译与上下文，到 LoongSuite Go 源码阅读、规则开发和兼容实验。循序渐进的中文交互学习指南。','A bilingual, progressive guide to Go compilation and context, LoongSuite Go source reading, rule development, and compatibility labs.'));$('.skip').textContent=ui('跳到正文','Skip to content');$('#search-title').textContent=ui('搜索知识、章节和源码','Search concepts, chapters, and source');$('#close-search').setAttribute('aria-label',ui('关闭搜索','Close search'));$('#global-search').setAttribute('aria-label',ui('关键词','Search terms'));$('#global-search').placeholder=ui('试试 context、toolexec、重复 Span…','Try context, toolexec, duplicate Span…');}
initStaticUI();document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
window.addEventListener('hashchange',render);render();
